void ExternalProcessImporterHost::Cancel() {

#if BUILDFLAG(ENABLE_AUX_BROWSER) && BUILDFLAG(IS_MAC)
  // Original41064cc prevents repeated ready notifications from creating a
  // second client. Preparation is after the real loaded-model/source gates.
  if (client_) {
    return;
  }
  if (!aux_preparation_complete_) {
    if (aux_preparation_started_) {
      return;
    }
    aux_preparation_started_ = true;
    if (aux_preparation_) {
      // A synchronous acknowledgment may delete this host. Do not access any
      // members after invoking the supplied preparation callback.
      auto prepare = std::move(aux_preparation_);
      std::move(prepare).Run(base::BindOnce(
          &ExternalProcessImporterHost::OnAuxPreparationComplete,
          weak_ptr_factory_.GetWeakPtr()));
      return;
    }
    aux_preparation_complete_ = true;
  }
#endif

